#![forbid(unsafe_code)]
//! Okkhor AI worker.
//!
//! A separate no-window process that owns the provider client. The daemon talks
//! to it over a private named pipe with its own token; the UI never talks to
//! this process directly. A worker crash, timeout, or missing key cannot stall
//! typing.
//!
//! Environment:
//! - `OKKHOR_AI_TOKEN` (required): hex token generated by the daemon.
//! - `OKKHOR_AI_PIPE` (optional): worker pipe name.
//! - `OKKHOR_OPENAI_API_KEY` (optional): provider key; missing means key-missing.
//! - `OKKHOR_AI_MODEL` (optional): default `gpt-6-luna`.
//! - `OKKHOR_OPENAI_BASE_URL` (optional): default `https://api.openai.com/v1`.
//! - `OKKHOR_ENV_FILE` (optional): a local `.env` from which missing variables
//!   may be read. `.env` is for development only and is git-ignored.

use std::collections::HashMap;
use std::env;
use std::path::PathBuf;
use std::process::ExitCode;
use std::sync::Arc;
use std::time::Duration;

use okkhor_ai::{
    AiError, AiPolicy, AiProvider, AiRequest, AiService, CancellationToken, DisabledProvider,
    OpenAiConfig, OpenAiProvider,
};
use okkhor_ipc::protocol::{
    AiCompleteParams, AiJobState, AiStatusInfo, NoArgs, Request, Response,
};
use okkhor_ipc::transport::{Handler, Server};
use okkhor_ipc::{ErrorCode, Token};

const DEFAULT_PIPE: &str = r"\\.\pipe\okkhor-ai-worker-v1";
const DEFAULT_MODEL: &str = "gpt-6-luna";
const DEFAULT_BASE_URL: &str = "https://api.openai.com/v1";
const DEFAULT_MAX_TOKENS: u32 = 512;
const DEFAULT_TEMPERATURE: f32 = 0.3;
const DEFAULT_TIMEOUT_MS: u64 = 15_000;
const PROMPT_VERSION: &str = "rewrite-v1";

struct WorkerHandler {
    service: Arc<AiService>,
    provider: &'static str,
    key_present: bool,
}

impl Handler for WorkerHandler {
    fn handle(&self, request: Request) -> Response {
        match request {
            Request::AiComplete(params) => self.complete(params),
            Request::AiStatus(NoArgs {}) => Response::AiStatus(AiStatusInfo {
                enabled: true,
                provider: self.provider.to_owned(),
                key_present: self.key_present,
                breaker_state: format!("{:?}", self.service.breaker_state()).to_lowercase(),
                active_jobs: 0,
            }),
            _ => Response::error(ErrorCode::UnknownMethod),
        }
    }
}

impl WorkerHandler {
    fn complete(&self, params: AiCompleteParams) -> Response {
        if let Err(code) = params.validate() {
            return Response::error(code);
        }

        let request = AiRequest {
            prompt: params.prompt,
            system: params.system,
            model: params.model.unwrap_or_else(|| DEFAULT_MODEL.to_owned()),
            max_tokens: params.max_tokens.unwrap_or(DEFAULT_MAX_TOKENS),
            temperature: params.temperature.unwrap_or(DEFAULT_TEMPERATURE),
            timeout: Duration::from_millis(params.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS)),
            prompt_version: PROMPT_VERSION.to_owned(),
        };

        match self
            .service
            .complete(&request, &CancellationToken::new())
        {
            Ok(response) => Response::AiJob(AiJobState::Done {
                text: response.text,
                model: response.model,
                input_tokens: response.usage.input_tokens,
                output_tokens: response.usage.output_tokens,
                latency_ms: response.latency_ms,
            }),
            Err(error) => Response::error(error_code(&error)),
        }
    }
}

fn error_code(error: &AiError) -> ErrorCode {
    match error {
        AiError::Disabled => ErrorCode::AiDisabled,
        AiError::KeyMissing => ErrorCode::AiKeyMissing,
        AiError::InvalidRequest => ErrorCode::InvalidRequest,
        AiError::Cancelled => ErrorCode::AiTimeout,
        AiError::Busy => ErrorCode::AiBusy,
        AiError::Timeout => ErrorCode::AiTimeout,
        AiError::Provider { .. } => ErrorCode::AiProviderError,
        AiError::InvalidResponse | AiError::Internal => ErrorCode::Internal,
    }
}

fn provider(
    key: Option<String>,
    model: &str,
) -> Result<(&'static str, bool, Box<dyn AiProvider + Send + Sync>), String> {
    let Some(key) = key.filter(|key| !key.trim().is_empty()) else {
        return Ok((
            "disabled",
            false,
            Box::new(DisabledProvider) as Box<dyn AiProvider + Send + Sync>,
        ));
    };
    let base_url = env::var("OKKHOR_OPENAI_BASE_URL")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| DEFAULT_BASE_URL.to_owned());
    let config = OpenAiConfig::new(key, base_url, model);
    let provider = OpenAiProvider::new(config).map_err(|error| format!("{error}"))?;
    Ok((
        "openai",
        true,
        Box::new(provider) as Box<dyn AiProvider + Send + Sync>,
    ))
}

/// Minimal `.env` reader. Returns an empty map when no file exists. Values are
/// used only to fill missing environment variables and are never logged.
fn load_env_file() -> HashMap<String, String> {
    let mut candidates = Vec::new();
    if let Some(path) = env::var_os("OKKHOR_ENV_FILE") {
        candidates.push(PathBuf::from(path));
    }
    if let Ok(cwd) = env::current_dir() {
        candidates.push(cwd.join(".env"));
    }
    if let Ok(exe) = env::current_exe() {
        if let Some(dir) = exe.parent() {
            candidates.push(dir.join(".env"));
            candidates.push(dir.join("..").join("..").join(".env"));
        }
    }

    for path in candidates {
        if let Ok(text) = std::fs::read_to_string(&path) {
            return parse_env(&text);
        }
    }
    HashMap::new()
}

fn parse_env(text: &str) -> HashMap<String, String> {
    let mut values = HashMap::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        let key = key.trim();
        if key.is_empty() {
            continue;
        }
        let value = value.trim().trim_matches('"').trim_matches('\'').to_owned();
        values.insert(key.to_owned(), value);
    }
    values
}

fn setting(env_file: &HashMap<String, String>, key: &str) -> Option<String> {
    env::var(key)
        .ok()
        .or_else(|| env_file.get(key).cloned())
        .filter(|value| !value.trim().is_empty())
}

#[tokio::main]
async fn main() -> ExitCode {
    let env_file = load_env_file();

    let Some(token_hex) = setting(&env_file, "OKKHOR_AI_TOKEN") else {
        eprintln!("okkhor-worker: missing OKKHOR_AI_TOKEN");
        return ExitCode::from(2);
    };
    let token = match Token::parse_hex(&token_hex) {
        Ok(token) => token,
        Err(_) => {
            eprintln!("okkhor-worker: invalid OKKHOR_AI_TOKEN");
            return ExitCode::from(2);
        }
    };

    let pipe = env::var("OKKHOR_AI_PIPE")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| DEFAULT_PIPE.to_owned());
    let model = setting(&env_file, "OKKHOR_AI_MODEL").unwrap_or_else(|| DEFAULT_MODEL.to_owned());

    let key = setting(&env_file, "OKKHOR_OPENAI_API_KEY");
    let (provider_name, key_present, provider) = match provider(key, &model) {
        Ok(value) => value,
        Err(_) => {
            eprintln!("okkhor-worker: invalid provider configuration");
            return ExitCode::from(2);
        }
    };

    let policy = AiPolicy {
        enabled: true,
        ..AiPolicy::default()
    };
    let service = Arc::new(AiService::new(policy, provider));
    let handler = Arc::new(WorkerHandler {
        service,
        provider: provider_name,
        key_present,
    });

    let server = Server::new(handler, token, env!("CARGO_PKG_VERSION"))
        .with_pipe_name(pipe)
        .with_request_deadline(Duration::from_secs(20));

    let (_shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
    match server.run(shutdown_rx).await {
        Ok(()) => ExitCode::SUCCESS,
        Err(_) => ExitCode::from(1),
    }
}
